{{ api_model('fiscal_settlement_revenue_lines') }}
select l.fiscal_line_id,l.dataset_id,l.source_row,l.fund_code,l.fund_label,a.value as amount,l.consolidation,l.counterpart_fund from {{ ref('int_fiscal_lines') }} l join {{ ref('int_fiscal_datasets') }} d using(dataset_id) join {{ ref('int_fiscal_amounts') }} a using(fiscal_line_id) where d.direction='revenue' and d.document_kind='settlement' and a.phase='executed' order by fiscal_line_id
